SELECT payment_id, metadata FROM payments WHERE payment_id IN (3, 8, 18);

SELECT metadata -> 'risk' -> 'score'  AS arrow,
       metadata -> 'risk' ->> 'score' AS double_arrow,
       pg_typeof(metadata -> 'risk' -> 'score')  AS arrow_type,
       pg_typeof(metadata -> 'risk' ->> 'score') AS double_arrow_type
FROM payments WHERE payment_id = 3;

SELECT count(*) FILTER (WHERE metadata -> 'risk' ->> 'score' > '50')      AS compared_as_text,
       count(*) FILTER (WHERE (metadata -> 'risk' ->> 'score')::int > 50) AS compared_as_int
FROM payments;

SELECT payment_id, metadata -> 'risk' ->> 'score' AS score
FROM payments
WHERE metadata -> 'risk' ->> 'score' > '50' AND (metadata -> 'risk' ->> 'score')::int <= 50
ORDER BY payment_id;

SELECT payment_id FROM payments
WHERE metadata @> '{"risk": {"rules": ["velocity"]}}'
ORDER BY payment_id;

SELECT '{"b": 1, "a": 2, "a": 3}'::json AS as_json, '{"b": 1, "a": 2, "a": 3}'::jsonb AS as_jsonb;
SELECT '{"channel": "web", "risk": {"score": 91'::jsonb;

SET search_path = big, public;
EXPLAIN (ANALYZE, COSTS OFF)
SELECT payment_id, card_id, amount_minor FROM payments
WHERE metadata @> '{"injected_dup": true}';

CREATE INDEX payments_metadata_gin ON payments USING gin (metadata);

EXPLAIN (ANALYZE, COSTS OFF)
SELECT payment_id, card_id, amount_minor FROM payments
WHERE metadata @> '{"injected_dup": true}';

EXPLAIN (ANALYZE, COSTS OFF)
SELECT payment_id, card_id, amount_minor FROM payments
WHERE metadata ->> 'injected_dup' = 'true';

SELECT pg_size_pretty(pg_relation_size('payments_metadata_gin')) AS gin_index,
       pg_size_pretty(pg_relation_size('payments')) AS payments_table;
DROP INDEX payments_metadata_gin;
RESET search_path;

