// 3. bind the arrays and read what changed
val changes = conn.prepareStatement(UPSERT_BATCH).use { ps ->
    ps.setArray(1, conn.createArrayOf("uuid", batch.map { it.uid }.toTypedArray()))
    ps.setArray(2, conn.createArrayOf("bigint", batch.map { it.cardId }.toTypedArray()))
    ps.setArray(3, conn.createArrayOf("bigint", batch.map { it.merchantId }.toTypedArray()))
    ps.setArray(4, conn.createArrayOf("bigint", batch.map { it.amountMinor }.toTypedArray()))
    ps.setArray(5, conn.createArrayOf("text", batch.map { it.status }.toTypedArray()))
    ps.setArray(6, conn.createArrayOf("timestamptz", batch.map { Timestamp.from(it.createdAt) }.toTypedArray()))
    ps.executeQuery().use { rs ->
        buildList { while (rs.next()) add(Change(rs.getLong(1), rs.getString(2), rs.getString(3))) }
    }
}

// 4. order of the two commits
conn.commit()                      // the payments are durable
consumer.commitSync()              // only now tell Kafka the batch is done
// a crash between the two lines: the batch comes back, and every row in it
// hits ON CONFLICT and changes nothing
